<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import AppState from '../components/AppState.vue'; import BookGrid from '../components/BookGrid.vue'; import { api } from '../lib/api'
const route=useRoute();const router=useRouter();const q=ref(typeof route.query.q==='string'?route.query.q:'');const books=ref<any[]>([]);const state=ref<'idle'|'loading'|'loaded'|'error'>('idle')
async function search(){if(!q.value.trim()){state.value='idle';books.value=[];return}state.value='loading';router.replace({query:{q:q.value.trim()}});try{books.value=(await api<{books:any[]}>(`/api/v1/books?q=${encodeURIComponent(q.value.trim())}`)).books;state.value='loaded'}catch{state.value='error'}} onMounted(search);watch(()=>route.query.q,(value)=>{if(typeof value==='string'&&value!==q.value){q.value=value;search()}})
</script>
<template><div><header class="page-header"><p class="eyebrow">Encontre sua próxima leitura</p><h1>Busca</h1></header><form class="search-hero" role="search" @submit.prevent="search"><label for="search-q">Título ou autor</label><div><input id="search-q" v-model="q" type="search" placeholder="Ex.: Machado de Assis" autofocus /><button class="button button--primary">Buscar</button></div></form><AppState v-if="state==='idle'" kind="empty" title="O acervo está à sua espera" message="Busque pelo título ou pelo nome do autor." /><AppState v-else-if="state==='loading'" kind="loading" /><AppState v-else-if="state==='error'" kind="error" title="A busca não pôde ser concluída"><button @click="search">Tentar novamente</button></AppState><section v-else><h2>{{ books.length }} {{ books.length===1?'livro encontrado':'livros encontrados' }}</h2><BookGrid v-if="books.length" :books="books" /><AppState v-else kind="empty" title="Nenhum resultado" message="Tente um termo mais curto ou confira a grafia." /></section></div></template>
